import{_ as s,H as n,f as i,i as p}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"13 | 基础：LLM-Wiki快速理解与入门","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾传统 RAG 的基本流程","slug":"回顾传统-rag-的基本流程","link":"#回顾传统-rag-的基本流程","children":[]},{"level":2,"title":"LLM-Wiki 到底是什么","slug":"llm-wiki-到底是什么","link":"#llm-wiki-到底是什么","children":[]},{"level":2,"title":"LLM-Wiki 与 RAG 的核心区别","slug":"llm-wiki-与-rag-的核心区别","link":"#llm-wiki-与-rag-的核心区别","children":[]},{"level":2,"title":"LLM-Wiki 的架构","slug":"llm-wiki-的架构","link":"#llm-wiki-的架构","children":[{"level":3,"title":"raw 层：原始资料的“仓库”","slug":"raw-层-原始资料的-仓库","link":"#raw-层-原始资料的-仓库","children":[]},{"level":3,"title":"wiki 层：AI 维护的核心知识库","slug":"wiki-层-ai-维护的核心知识库","link":"#wiki-层-ai-维护的核心知识库","children":[]},{"level":3,"title":"schema 层：如何在 Wiki 层组织知识库的规则","slug":"schema-层-如何在-wiki-层组织知识库的规则","link":"#schema-层-如何在-wiki-层组织知识库的规则","children":[]},{"level":3,"title":"index.md：Wiki 的目录导航","slug":"index-md-wiki-的目录导航","link":"#index-md-wiki-的目录导航","children":[]},{"level":3,"title":"log.md：审计日志","slug":"log-md-审计日志","link":"#log-md-审计日志","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"HarnessAgent脚手架实战课/13｜基础：LLM-Wiki快速理解与入门.md","filePath":"HarnessAgent脚手架实战课/13｜基础：LLM-Wiki快速理解与入门.md","lastUpdated":1795487647000}'),l={name:"HarnessAgent脚手架实战课/13｜基础：LLM-Wiki快速理解与入门.md"};function e(t,a,d,c,o,r){return n(),i("div",null,[...a[0]||(a[0]=[p(`<h1 id="_13-基础-llm-wiki快速理解与入门" tabindex="-1">13 | 基础：LLM-Wiki快速理解与入门 <a class="header-anchor" href="#_13-基础-llm-wiki快速理解与入门" aria-label="Permalink to &quot;13 | 基础：LLM-Wiki快速理解与入门&quot;">​</a></h1><p>你好，我是邢云阳。</p><p>2026 年 4 月，人工智能科学家以及著名教育家 Andrej Karpathy（卡帕西）提出了一种名为LLM-Wiki 的个人知识编译系统，用来重构他自己的研究知识管理方式。无论他本人，还是这次他提出的概念，都在 AI 圈内非常有影响力，该帖子一经发布便迅速在技术社区引发传播，累计浏览量超过 2000 万，直接成为当月讨论度最高的一个 AI 事件。</p><p>那为什么这样一个看似“个人笔记系统”的方案会引爆整个互联网？本质在于他第一次把 LLM 的使用范式从“对话式工具”推向了“知识生产系统”，模型不再是被动回答问题，而是主动参与知识管理、结构生成与长期演化。</p><p>这节课，我们就来好好地聊一聊 LLM-Wiki。</p><h2 id="回顾传统-rag-的基本流程" tabindex="-1">回顾传统 RAG 的基本流程 <a class="header-anchor" href="#回顾传统-rag-的基本流程" aria-label="Permalink to &quot;回顾传统 RAG 的基本流程&quot;">​</a></h2><p>正式介绍 LLM-Wiki 之前，我们稍微回顾一下大家更熟悉的 RAG（检索增强生成）。</p><p>RAG 的基本逻辑是：每次用户提问时，从原始文档中检索出相关片段，然后把片段塞进prompt，让模型基于这些片段生成答案。对于简单的问答场景，这套方法非常有效。比如问“某公司 2025 年营收是多少”，从年报里检索出对应段落，模型直接回答即可。</p><p>但当我们做一些更复杂的研究型任务时，RAG 的短板就会暴露出来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13/1.png" alt=""></a></p><p>第一，上下文无法累积。每次提问都是独立的检索 + 生成过程。上一次分析中得到的结论、修正过的数据、排除过的假设，不会自动进入下一次对话。如果你要连续追踪一个行业三个月，就得反复把背景信息喂给模型。</p><p>第二，跨文档关联弱。单独检索某份文档里的片段，难以发现多份资料之间的矛盾和联系。比如 A 研报说某公司毛利率上升是因为产品结构优化，B 研报说是因为原材料降价，C 研报又提到行业竞争加剧。RAG 很难主动把它们放在同一页面上做对比和关联。</p><p>第三，知识无法形成复利。原始资料永远是“原料”，AI 每次都要重新理解、重新总结。研究做得越久，重复劳动越多，而不是越用越聪明。</p><p>LLM-Wiki 的核心思想，就是把这些“一次性理解”变成“可持续维护的知识资产”。</p><h2 id="llm-wiki-到底是什么" tabindex="-1">LLM-Wiki 到底是什么 <a class="header-anchor" href="#llm-wiki-到底是什么" aria-label="Permalink to &quot;LLM-Wiki 到底是什么&quot;">​</a></h2><p>Andrej Karpathy 提出，与其每次让 AI 临时读原始文档，不如让 AI 先把资料“编译”成一个结构化的、互相链接的 Markdown 页面网络，然后基于这个 Wiki 来回答问题。这其实有点像之前的知识图谱，各个知识不是孤立的片段，而是存在联系。</p><p>LLM-Wiki 整个构建流程可以概括为三步：</p><ol><li><p>阅读资料：AI 读取原始文档（PDF、网页、笔记等）。</p></li><li><p>提取与编译：从中提取关键实体、概念、关系，按照预定格式写成 Markdown 页面。</p></li><li><p>持续维护：新资料进来时，更新已有页面、添加链接、标记矛盾，让知识库像 Wiki 一样生长。</p></li></ol><p>最终形成的是一个纯 Markdown + 文件系统的知识库。你可以用 VS Code、Obsidian、Git 直接查看和管理它，不依赖任何黑盒向量数据库。</p><h2 id="llm-wiki-与-rag-的核心区别" tabindex="-1">LLM-Wiki 与 RAG 的核心区别 <a class="header-anchor" href="#llm-wiki-与-rag-的核心区别" aria-label="Permalink to &quot;LLM-Wiki 与 RAG 的核心区别&quot;">​</a></h2><p>为了更直观地理解两者的差异，我把它们放在一起对比。</p><ul><li>传统 RAGLLM-Wiki</li></ul><p>维度</p><ul><li>先编译成结构化 Wiki，再基于 Wiki 查询</li></ul><p>工作方式</p><ul><li>每次提问时临时检索片段</li></ul><p>知识状态</p><ul><li>无状态，每次从零开始有状态，知识持续累积</li></ul><p>上下文能力</p><ul><li><p>受限于单次检索窗口跨页面、跨文档的关联被显式维护</p></li><li><p>纯 Markdown + Git，每次变更可审计</p></li></ul><p>可审计性</p><ul><li>黑盒向量库，难追溯</li></ul><p>知识复利</p><ul><li><p>低，重复处理原始资料高，新资料在已有结构上增量生长</p></li><li><p>可以在编译阶段审查、修正 Wiki 页面</p></li></ul><p>人工介入</p><ul><li>主要在提问和审答案</li></ul><h2 id="llm-wiki-的架构" tabindex="-1">LLM-Wiki 的架构 <a class="header-anchor" href="#llm-wiki-的架构" aria-label="Permalink to &quot;LLM-Wiki 的架构&quot;">​</a></h2><p>那在粗略了解了 LLM-Wiki 的概念后，接下来，我们再详细讲解一下 LLM-Wiki 的架构，为后续构建 LLM-Wiki 打下基础。LLM-Wiki 的架构可以总结为三层加两个关键文件，我们依次来看。</p><h3 id="raw-层-原始资料的-仓库" tabindex="-1">raw 层：原始资料的“仓库” <a class="header-anchor" href="#raw-层-原始资料的-仓库" aria-label="Permalink to &quot;raw 层：原始资料的“仓库”&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/ 目录存放的是原始、不可变的资料。可以是 PDF 转成的 Markdown、爬取的文章、你</span></span></code></pre></div><p>的读书笔记、会议录音转录稿等等。这一层只供 AI 读取，不直接对外提供答案。</p><p>它的作用是保留“证据”。当 Wiki 中的某个结论需要复核时，你可以随时回到 raw 层，找到最初的出处。</p><h3 id="wiki-层-ai-维护的核心知识库" tabindex="-1">wiki 层：AI 维护的核心知识库 <a class="header-anchor" href="#wiki-层-ai-维护的核心知识库" aria-label="Permalink to &quot;wiki 层：AI 维护的核心知识库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wiki/ 目录是 LLM-Wiki 的核心。里面的每一个 Markdown 页面，都是 AI 根据 schema 规则</span></span></code></pre></div><p>编译出来的知识单元。常见的页面类型包括：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index.md：Wiki 的总目录和导航。</span></span>
<span class="line"><span>entities/：实体页，比如人、公司、技术、产品等。</span></span>
<span class="line"><span>concepts/：概念页，比如“DCF 估值”、“注意力机制”。</span></span>
<span class="line"><span>summaries/：单份资料或单次会议的总结。</span></span>
<span class="line"><span>synthesis/：综合对比页，比如“燕京啤酒 vs 青岛啤酒”、“PE 估值 vs DCF 估值”。</span></span></code></pre></div><p>这些页面之间通过 Markdown 链接互相引用，形成一个真正的知识网络。</p><h3 id="schema-层-如何在-wiki-层组织知识库的规则" tabindex="-1">schema 层：如何在 Wiki 层组织知识库的规则 <a class="header-anchor" href="#schema-层-如何在-wiki-层组织知识库的规则" aria-label="Permalink to &quot;schema 层：如何在 Wiki 层组织知识库的规则&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>schema.md 是整个 Wiki 的维护规则。它告诉 AI：</span></span></code></pre></div><ul><li><p>什么样的内容应该新建一个页面？</p></li><li><p>每个页面应该包含哪些字段？</p></li><li><p>页面之间如何建立链接？</p></li><li><p>遇到矛盾信息时应该怎么标记？</p></li><li><p>index.md 和 log.md 应该怎么更新？</p></li></ul><p>schema 是你的业务规则在 Wiki 层面的体现。一个好的 schema 能让 AI 持续、稳定地产出结构一致的知识页面。部分 schema.md 的内容示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Wiki Schema — 投研知识库结构定义</span></span>
<span class="line"><span>&gt; 本文件定义 Wiki 的页面类型、命名约定、frontmatter 规范、工作流。</span></span>
<span class="line"><span>&gt; 由你和 LLM 共同迭代演进。当前版本: v1.0</span></span>
<span class="line"><span>## 三层架构</span></span>
<span class="line"><span>| 层级 | 路径 | 性质 | 说明 |</span></span>
<span class="line"><span>|------|------|------|------|</span></span>
<span class="line"><span>| Raw Sources | \`/data/raw/\` | 只读,不可变 | 原始资料(研报 PDF、新闻、公告、复盘) |</span></span>
<span class="line"><span>| Wiki | \`/data/wiki/\` | LLM 读写 | 结构化 Markdown 知识库 |</span></span>
<span class="line"><span>| Schema | \`/data/schema.md\` | 本文件 | Wiki 结构与工作流配置 |</span></span>
<span class="line"><span>## 页面类型与命名</span></span>
<span class="line"><span>| 类型 | 命名格式 | 示例 | 存放位置 |</span></span>
<span class="line"><span>|------|---------|------|---------|</span></span>
<span class="line"><span>| 个股档案 | \`{代码}-{公司简称}.md\` | \`300750-宁德时代.md\` | \`/data/wiki/\` |</span></span>
<span class="line"><span>| 行业综述 | \`industry-{行业名}.md\` | \`industry-动力电池.md\` | \`/data/wiki/\` |</span></span>
<span class="line"><span>| 宏观/概念 | \`macro-{概念名}.md\` | \`macro-美联储加息.md\` | \`/data/wiki/\` |</span></span>
<span class="line"><span>| 资料摘要 | \`source-{关键词或代码}.md\` | \`source-300750-宁德时代2025年报.md\` | \`/data</span></span>
<span class="line"><span>| 策略/复盘 | \`strategy-{策略名}.md\` | \`strategy-网格交易复盘.md\` | \`/data/wiki/\` |</span></span>
<span class="line"><span>## 关键文件</span></span>
<span class="line"><span>- **\`/data/wiki/index.md\`** — 内容总览目录。按类别(个股/行业/宏观/策略/资料)组织,每条含链接</span></span>
<span class="line"><span>- **\`/data/wiki/log.md\`** — 投研操作日志。按时间顺序追加(新事件在上方),格式如 \`## [YYYY-M</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>## 交叉引用原则</span></span>
<span class="line"><span>- **Wikilink** 风格:\`[[300750-宁德时代]]\` — 支持 Obsidian 图谱视图</span></span>
<span class="line"><span>- 每个个股页底部都要有&quot;来源&quot;链接,指回资料摘要页</span></span>
<span class="line"><span>- 摘要页末尾列出&quot;相关概念&quot;,形成概念网络</span></span>
<span class="line"><span>- **标注跨资料关联**:多篇研报提到相似观点时,在页面中明确标注</span></span>
<span class="line"><span>- **标注矛盾观点**:不同资料的冲突要明确标注,不偷偷覆盖</span></span></code></pre></div><p>这样，根据以上分层，一个最简单的项目结构示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-wiki/</span></span>
<span class="line"><span>├── raw/                 # 原始不可变资料</span></span>
<span class="line"><span>│   ├── 燕京啤酒2025年报.md</span></span>
<span class="line"><span>│   └── 啤酒行业研究报告.md</span></span>
<span class="line"><span>├── wiki/                # AI 维护的核心知识库</span></span>
<span class="line"><span>│   ├── index.md         # 总目录导航</span></span>
<span class="line"><span>│   ├── entities/</span></span>
<span class="line"><span>│   │   └── 燕京啤酒.md</span></span>
<span class="line"><span>│   ├── concepts/</span></span>
<span class="line"><span>│   │   └── 毛利率.md</span></span>
<span class="line"><span>│   ├── summaries/</span></span>
<span class="line"><span>│   │   └── 燕京啤酒2025年报摘要.md</span></span>
<span class="line"><span>│   └── synthesis/</span></span>
<span class="line"><span>│       └── 燕京啤酒vs青岛啤酒.md</span></span>
<span class="line"><span>├── schema.md            # 维护规则</span></span>
<span class="line"><span>└── .git/                # 用 Git 跟踪变化</span></span></code></pre></div><p>在这三层中，有两个文件非常重要，每一次更新知识，这两个文件都会跟着被 AI 更新。</p><h3 id="index-md-wiki-的目录导航" tabindex="-1">index.md：Wiki 的目录导航 <a class="header-anchor" href="#index-md-wiki-的目录导航" aria-label="Permalink to &quot;index.md：Wiki 的目录导航&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index.md 相当于整本百科全书的目录。它会列出当前 Wiki 中有哪些实体、概念、总结和综</span></span></code></pre></div><p>合分析，方便 AI 在后续任务中快速定位到相关页面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>比如一个投研场景下的 index.md 可以设计成这样：</span></span>
<span class="line"><span>**# 投研 Wiki 索引**</span></span>
<span class="line"><span>**## 实体**</span></span>
<span class="line"><span>- [[燕京啤酒]] — 国内啤酒行业上市公司</span></span>
<span class="line"><span>- [[青岛啤酒]] — 国内啤酒行业龙头</span></span>
<span class="line"><span>**## 概念**</span></span>
<span class="line"><span>- [[毛利率]] — 营业收入减去营业成本后的比率</span></span>
<span class="line"><span>- [[DCF 估值]] — 现金流折现估值方法</span></span>
<span class="line"><span>**## 总结**</span></span>
<span class="line"><span>- [[燕京啤酒2025年报摘要]]</span></span>
<span class="line"><span>**## 综合分析**</span></span>
<span class="line"><span>- [[燕京啤酒vs青岛啤酒]] — 盈利能力与估值对比</span></span></code></pre></div><h3 id="log-md-审计日志" tabindex="-1">log.md：审计日志 <a class="header-anchor" href="#log-md-审计日志" aria-label="Permalink to &quot;log.md：审计日志&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log.md 记录 Wiki 的变更历史。每次 AI 新增、修改、合并页面时，都会在这里追加一条记</span></span></code></pre></div><p>录，包括变更时间、涉及页面、变更原因和原始资料来源。</p><p>它的作用类似 Git 的提交日志，但更适合人类快速阅读。当你发现 Wiki 中某个结论有问题时，可以通过 log.md 快速追溯到它是基于哪份资料、在哪次更新中产生的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**# Wiki 变更日志**</span></span>
<span class="line"><span>**## 2026-07-18**</span></span>
<span class="line"><span>- 新增 [[燕京啤酒]] 实体页，来源：raw/燕京啤酒2025年报.md</span></span>
<span class="line"><span>- 更新 [[毛利率]] 概念页，补充啤酒行业平均水平</span></span>
<span class="line"><span>- 新增 [[燕京啤酒vs青岛啤酒]] 综合分析页</span></span></code></pre></div><p>到这里，对于 LLM-Wiki 的入门和理解也就差不多了，那我们具体该如何构建出这个知识库？需要写什么样的代码来实现吗？这些内容我们下节课讲解。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们介绍了 LLM-Wiki 这种让 AI 知识“长住”下来的工程化思路。</p><p>回顾一下核心收获：</p><ul><li><p>LLM-Wiki 不是替代 RAG，而是把“临时检索”升级为“持续维护的知识库”。</p></li><li><p>它的核心流程是：阅读 raw 资料 → 按 schema 编译成 Markdown 页面 → 通过链接形成知识网络 → 持续更新维护。</p></li><li><p>三层架构分别是 raw 层（原始资料）、wiki 层（结构化知识）和 schema 层（维护规则）。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index.md 负责导航，log.md 负责审计，两者都应由 AI 自动维护。</span></span></code></pre></div><ul><li>纯 Markdown + 文件系统 + Git 的组合，让知识库对人类和 AI 都友好，同时具备可审计和可复利增长的能力。</li></ul><p>那在今年以来，大家会发现，好多 AI 圈提出的新的思路，好像有点“倒退”的嫌疑。比如用 CLI替代工具，用 Markdown 方案来替代向量数据库方案等等。那这其实不是倒退，而是经过了前面几年探索，走了很多弯路之后的理性回归。</p><p>就拿 RAG 来讲，深入实践过的同学都知道，其实我们很难在大规模知识场景中，将召回率提升到很高的水平，这是 RAG 本身的机制决定的。真正想要召回率高，需要多花钱上知识图谱，因为图谱存在实体间的关联，才能大幅提升关联知识的召回率。但这个过程中由于需要让AI 理解知识，提取实体，是很费 token 的。</p><p>所以其实在真正项目中，很多时候都是把知识直接存文件，然后在提示词中写死，让 AI 在需要的场景中去读取。这种看似比较 low 的做法，反而会让召回率大大提升。那大家看今天的Skill 以及 LLM-Wiki，其实现思路就有上面所述方法的影子，只不过会把方案优化得更好，这便是理性回归。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请结合你自己的工作场景思考：</p><ul><li><p>你当前的工作里，有哪些知识或资料是反复被 AI 重新处理的？它们是否适合沉淀成 LLM-Wiki？</p></li><li><p>如果你来根据你的业务场景设计 schema.md，你会定义哪些页面类型和链接规则？</p></li></ul><p>期待看到你在留言区展示思考过程，我们一起探讨。如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,78)])])}const m=s(l,[["render",e]]);export{k as __pageData,m as default};
